(6126777, 902489, 15711, '<td valign="top">That looks cropped, but maybe not. :)</td>', 'That looks cropped, but maybe not. :)', '2010-08-11 01:15:47.000000', NULL, 1),
(6126787, 902291, 15711, '<td valign="top">Probably the best technically done shot of the challenge.  Bravo.</td>', 'Probably the best technically done shot of the challenge.  Bravo.', '2010-08-11 01:19:03.000000', NULL, 1),
(6126811, 902932, 115307, '<td valign="top">The white balance is  off in this picture. However, this is a great concept and one of the few images in this challenge that actually cleverly incorporates the title. 7</td>', 'The white balance is  off in this picture. However, this is a great concept and one of the few images in this challenge that actually cleverly incorporates the title. 7', '2010-08-11 01:30:22.000000', NULL, 1),
(6126819, 902714, 75618, '<td valign="top">It seems like he''s just waiting for someone rather than someone who is underprivileged (homeless) but this is one of the better shots. Love the dark tones, hopefully it''s within the rules. 7</td>', 'It seems like he''s just waiting for someone rather than someone who is underprivileged (homeless) but this is one of the better shots. Love the dark tones, hopefully it''s within the rules. 7', '2010-08-11 01:33:39.000000', NULL, 1),
(6126823, 902764, 115307, '<td valign="top">Oh, I hope this ribbons. Very clever idea, cute, and well photographed. I am amazed that this is minimal editing.<br/>Most of the pictures in this challenge have titles that are quite a stretch. This is one of the very few where the title is the original concept. Awesome job 10!</td>', 'Oh, I hope this ribbons. Very clever idea, cute, and well photographed. I am amazed that this is minimal editing.Most of the pictures in this challenge have titles that are quite a stretch. This is one of the very few where the title is the original concept. Awesome job 10!', '2010-08-11 01:35:12.000000', NULL, 1),
(6126827, 902965, 75618, '<td valign="top">Great shot but it doesn''t really illustrate understated. It''s quite the opposite for me with the heavy make-up and embellishment on the shoulder. 6</td>', 'Great shot but it doesn''t really illustrate understated. It''s quite the opposite for me with the heavy make-up and embellishment on the shoulder. 6', '2010-08-11 01:37:22.000000', NULL, 1),
(6126956, 902238, 96751, '<td valign="top">Nice dof.</td>', 'Nice dof.', '2010-08-11 03:28:45.000000', NULL, 1),
(6126957, 902575, 96751, '<td valign="top">Pretty cool for minimal!</td>', 'Pretty cool for minimal!', '2010-08-11 03:29:10.000000', NULL, 1),
(6126958, 902714, 96751, '<td valign="top">Great street scene.  Love the high contrast.</td>', 'Great street scene.  Love the high contrast.', '2010-08-11 03:29:32.000000', NULL, 1),
(6126984, 902627, 108580, '<td valign="top">ROFL, very crisp and neat, great expression for "from the camera" unedited, well done.</td>', 'ROFL, very crisp and neat, great expression for "from the camera" unedited, well done.', '2010-08-11 04:04:56.000000', NULL, 1),
(6126989, 902754, 108580, '<td valign="top">LOL @ title. Lovely shot of a very rare species. In the wild you never (or very seldom) get this close. They are endangered.</td>', 'LOL @ title. Lovely shot of a very rare species. In the wild you never (or very seldom) get this close. They are endangered.', '2010-08-11 04:08:13.000000', NULL, 1),
(6126990, 902704, 108580, '<td valign="top">Beautifully done.</td>', 'Beautifully done.', '2010-08-11 04:08:40.000000', NULL, 1),
(6126991, 902697, 108580, '<td valign="top">Lol creative title...he needs Ponds? Or Nivea?</td>', 'Lol creative title...he needs Ponds? Or Nivea?', '2010-08-11 04:09:28.000000', NULL, 1),
(6127024, 902682, 108580, '<td valign="top">Excellent, close, detailed. Perhaps needed -0.3EV to kill that highlight.<br/>Great from the camera shot.</td>', 'Excellent, close, detailed. Perhaps needed -0.3EV to kill that highlight.Great from the camera shot.', '2010-08-11 05:03:41.000000', NULL, 1),
(6127034, 901747, 108580, '<td valign="top">Stunning, a winner. You used lighting and background instead of Photoshop. Well done...</td>', 'Stunning, a winner. You used lighting and background instead of Photoshop. Well done...', '2010-08-11 05:18:55.000000', NULL, 1),
(6127035, 902969, 108580, '<td valign="top">Fantastic shot...</td>', 'Fantastic shot...', '2010-08-11 05:19:40.000000', NULL, 1),
