(6127050, 902725, 108580, '<td valign="top">Thought provoking image, well done</td>', 'Thought provoking image, well done', '2010-08-11 05:48:55.000000', NULL, 1),
(6127051, 902733, 108580, '<td valign="top">Awesome.</td>', 'Awesome.', '2010-08-11 05:49:07.000000', NULL, 1),
(6127052, 902291, 108580, '<td valign="top">Lovely shot as is from cam, well done!</td>', 'Lovely shot as is from cam, well done!', '2010-08-11 05:49:32.000000', NULL, 1),
(6127077, 902632, 94437, '<td valign="top">I havent been there for a while, but I am guessing it is South Land shopping center. Tho I could be wrong.<br/>Nice thought process to fit this into the Under challenge.<br/>Decent photo.</td>', 'I havent been there for a while, but I am guessing it is South Land shopping center. Tho I could be wrong.Nice thought process to fit this into the Under challenge.Decent photo.', '2010-08-11 06:57:29.000000', NULL, 1),
(6127102, 902647, 117095, '<td valign="top">I had this same exact camera as a kid.</td>', 'I had this same exact camera as a kid.', '2010-08-11 07:38:14.000000', NULL, 1),
(6127132, 902590, 23484, '<td valign="top">Excellent perspective and nice conversion.</td>', 'Excellent perspective and nice conversion.', '2010-08-11 08:27:04.000000', NULL, 1),
(6127135, 902499, 23484, '<td valign="top">I really like the processing on this. Nice.</td>', 'I really like the processing on this. Nice.', '2010-08-11 08:27:47.000000', NULL, 1),
(6127136, 902721, 23484, '<td valign="top">Great perspective and nice B&amp;W.</td>', 'Great perspective and nice B&W.', '2010-08-11 08:28:28.000000', NULL, 1),
(6127137, 902286, 23484, '<td valign="top">Very nice wide angle view. Good composition.</td>', 'Very nice wide angle view. Good composition.', '2010-08-11 08:28:58.000000', NULL, 1),
(6127139, 902580, 23484, '<td valign="top">I really like the colors here. Nice angle.</td>', 'I really like the colors here. Nice angle.', '2010-08-11 08:29:48.000000', NULL, 1),
(6127146, 901881, 108580, '<td valign="top">Awesome shot, direct from camera, great control.</td>', 'Awesome shot, direct from camera, great control.', '2010-08-11 08:33:35.000000', NULL, 1),
(6127148, 902575, 108580, '<td valign="top">Super shot</td>', 'Super shot', '2010-08-11 08:34:52.000000', NULL, 1),
(6127150, 902590, 108580, '<td valign="top">Awesome take on the challenge rules. Superb long exposure and B&amp;W conversion.</td>', 'Awesome take on the challenge rules. Superb long exposure and B&W conversion.', '2010-08-11 08:38:45.000000', NULL, 1),
(6127151, 902634, 108580, '<td valign="top">Hehe, hello Clark...nice one</td>', 'Hehe, hello Clark...nice one', '2010-08-11 08:40:15.000000', NULL, 1),
(6127152, 902764, 108580, '<td valign="top">Lovely shot.</td>', 'Lovely shot.', '2010-08-11 08:40:30.000000', NULL, 1),
(6127167, 902764, 43774, '<td valign="top">Cute!!</td>', 'Cute!!', '2010-08-11 08:57:37.000000', NULL, 1),
(6127216, 902699, 97774, '<td valign="top">You nailed it with your title, high marks from me.</td>', 'You nailed it with your title, high marks from me.', '2010-08-11 10:01:27.000000', NULL, 1),
(6127218, 902620, 114225, '<td valign="top">Very nice photo. Lots of great details, good exposure, and nice triangle based composition.</td>', 'Very nice photo. Lots of great details, good exposure, and nice triangle based composition.', '2010-08-11 10:03:41.000000', NULL, 1),
(6127221, 902634, 114225, '<td valign="top">Nice job centering the RV under the rainbow. However, this comes off as too much of a snapshot due to the other RVs in the background.</td>', 'Nice job centering the RV under the rainbow. However, this comes off as too much of a snapshot due to the other RVs in the background.', '2010-08-11 10:05:30.000000', NULL, 1),
(6127222, 902933, 114225, '<td valign="top">Good attempt. What this is really missing is super sharp focus on the person, If it had that, combined with a bit of background blur, I think it would have done better.</td>', 'Good attempt. What this is really missing is super sharp focus on the person, If it had that, combined with a bit of background blur, I think it would have done better.', '2010-08-11 10:06:09.000000', NULL, 1),
(6127223, 902797, 114225, '<td valign="top">I like the leading line based composition, and use of the "rule of odds" for subjects.<br/>I bet you wish this were an advanced challenge, as this would be a perfect photo for HDR techniques.</td>', 'I like the leading line based composition, and use of the "rule of odds" for subjects.I bet you wish this were an advanced challenge, as this would be a perfect photo for HDR techniques.', '2010-08-11 10:08:47.000000', NULL, 1),
(6127224, 902148, 114225, '<td valign="top">Hmmm, I''m torn. Partly I would like to see him with a black jacket (think Men in Black style) but maybe that wouldn''t be Undercover anymore. Either way, what''s really hurting this photo (in my eyes) is the very soft focus on the subject. The background has nice blurring though.</td>', 'Hmmm, I''m torn. Partly I would like to see him with a black jacket (think Men in Black style) but maybe that wouldn''t be Undercover anymore. Either way, what''s really hurting this photo (in my eyes) is the very soft focus on the subject. The background has nice blurring though.', '2010-08-11 10:10:36.000000', NULL, 1),
(6127226, 902725, 114225, '<td valign="top">Interesting idea for this challenge.<br/>For me, there is just too much going on here. Maybe if you could have focused more on just a row or two of cubes, instead of trying to fit the whole room in the frame, it would have been more pleasant to my eyes.</td>', 'Interesting idea for this challenge.For me, there is just too much going on here. Maybe if you could have focused more on just a row or two of cubes, instead of trying to fit the whole room in the frame, it would have been more pleasant to my eyes.', '2010-08-11 10:12:39.000000', NULL, 1),
(6127240, 902569, 114225, '<td valign="top">Nice balance in this composition. In most cases, it would be preferable to not have all those people in the shot, but when showing size, it really helps. Very good job on the exposure, as you have detail in the sky and the tower.</td>', 'Nice balance in this composition. In most cases, it would be preferable to not have all those people in the shot, but when showing size, it really helps. Very good job on the exposure, as you have detail in the sky and the tower.', '2010-08-11 10:19:03.000000', NULL, 1),
(6127243, 902914, 114225, '<td valign="top">Nice use of panning. I like how you went with a relatively short shutter so that the background wasn''t completely obliterated (it gives a sense of context to the photo).</td>', 'Nice use of panning. I like how you went with a relatively short shutter so that the background wasn''t completely obliterated (it gives a sense of context to the photo).', '2010-08-11 10:20:08.000000', NULL, 1),
(6127245, 902049, 114225, '<td valign="top">A bit of a stretch, but I will let it slide. Good use of framing with the trees, and very nice details. B&amp;W was a good choice for this photo.</td>', 'A bit of a stretch, but I will let it slide. Good use of framing with the trees, and very nice details. B&W was a good choice for this photo.', '2010-08-11 10:21:15.000000', NULL, 1),
(6127249, 902291, 114225, '<td valign="top">Creative title. Good composition, but the focus point seems to be just off. Looks like the tail was focused instead on the head/eye.</td>', 'Creative title. Good composition, but the focus point seems to be just off. Looks like the tail was focused instead on the head/eye.', '2010-08-11 10:22:05.000000', NULL, 1),
(6127252, 902627, 114225, '<td valign="top">Great facial expression, that really makes the title appropriate. Good lighting. I would have probably chosen a tighter crop to eliminate the other person from the shot (after seeing the result on the LCD).</td>', 'Great facial expression, that really makes the title appropriate. Good lighting. I would have probably chosen a tighter crop to eliminate the other person from the shot (after seeing the result on the LCD).', '2010-08-11 10:23:26.000000', NULL, 1),
(6127257, 902714, 114225, '<td valign="top">Nice mood to this, and good details. I think I would have chosen to re-shoot without the walking people as the ghost effect isn''t appealing to me.</td>', 'Nice mood to this, and good details. I think I would have chosen to re-shoot without the walking people as the ghost effect isn''t appealing to me.', '2010-08-11 10:24:25.000000', NULL, 1),
(6127259, 902715, 114225, '<td valign="top">Nice details and textures in the leaves. The green feels somewhat over-saturated (maybe it''s a notch or two over exposed?)</td>', 'Nice details and textures in the leaves. The green feels somewhat over-saturated (maybe it''s a notch or two over exposed?)', '2010-08-11 10:25:36.000000', NULL, 1),
(6127261, 902704, 114225, '<td valign="top">I was wondering if someone would try this. I like the clarity of the dashboard, and the dreaminess/waviness of the outside definitely adds to the drunk feeling.</td>', 'I was wondering if someone would try this. I like the clarity of the dashboard, and the dreaminess/waviness of the outside definitely adds to the drunk feeling.', '2010-08-11 10:27:39.000000', NULL, 1),
(6127262, 902596, 114225, '<td valign="top">Nice job getting low on the perspective. This is a bit underexposed (maybe shooting with exposure bracketing could have given you a properly exposed image).</td>', 'Nice job getting low on the perspective. This is a bit underexposed (maybe shooting with exposure bracketing could have given you a properly exposed image).', '2010-08-11 10:29:24.000000', NULL, 1),
(6127267, 902374, 114225, '<td valign="top">Good spin on "under construction." Nicely set up, and good lighting.</td>', 'Good spin on "under construction." Nicely set up, and good lighting.', '2010-08-11 10:30:47.000000', NULL, 1),
(6127271, 902387, 114225, '<td valign="top">Haha! Great setup. Good low perspective, and nice job with the background.</td>', 'Haha! Great setup. Good low perspective, and nice job with the background.', '2010-08-11 10:33:06.000000', NULL, 1),
(6127273, 902882, 114225, '<td valign="top">This really turned out cool! A bit of a stretch for this challenge, as I don''t believe "Underfocused" is a real word or term.</td>', 'This really turned out cool! A bit of a stretch for this challenge, as I don''t believe "Underfocused" is a real word or term.', '2010-08-11 10:34:14.000000', NULL, 1),
(6127275, 902358, 114225, '<td valign="top">Good use of negative space. I like the sun shining trough, adds a lot to the photo.</td>', 'Good use of negative space. I like the sun shining trough, adds a lot to the photo.', '2010-08-11 10:34:45.000000', NULL, 1),
(6127277, 902754, 114225, '<td valign="top">Creative title. Good exposure, composition, and details.</td>', 'Creative title. Good exposure, composition, and details.', '2010-08-11 10:35:30.000000', NULL, 1),
(6127280, 902583, 114225, '<td valign="top">Good idea for the challenge. The lighting on this is very harsh. Looks like it''s natural light from the window, which can be hard to control (and in this case, caused some major blown out highlights). One way to help is to diffuse the light, maybe by putting a white sheet in front of the window.</td>', 'Good idea for the challenge. The lighting on this is very harsh. Looks like it''s natural light from the window, which can be hard to control (and in this case, caused some major blown out highlights). One way to help is to diffuse the light, maybe by putting a white sheet in front of the window.', '2010-08-11 10:37:50.000000', NULL, 1),
(6127281, 902632, 114225, '<td valign="top">This photo is a bit too busy for me. There is a lot going on, with no real focus. My suggestion would be to think about how to tell a story with this scene, and key in on that instead of trying to get everything in the frame.</td>', 'This photo is a bit too busy for me. There is a lot going on, with no real focus. My suggestion would be to think about how to tell a story with this scene, and key in on that instead of trying to get everything in the frame.', '2010-08-11 10:39:28.000000', NULL, 1),
(6127283, 902964, 114225, '<td valign="top">A very nice abstract feel to this photo. The black and white was a really good choice.</td>', 'A very nice abstract feel to this photo. The black and white was a really good choice.', '2010-08-11 10:40:57.000000', NULL, 1),
(6127285, 902932, 114225, '<td valign="top">Cute idea. Nice composition and lighting.</td>', 'Cute idea. Nice composition and lighting.', '2010-08-11 10:42:59.000000', NULL, 1),
(6127289, 902593, 114225, '<td valign="top">Good use of diagonal lines. The photo feels a little bit underexposed, which mainly means we cannot see the fine details.</td>', 'Good use of diagonal lines. The photo feels a little bit underexposed, which mainly means we cannot see the fine details.', '2010-08-11 10:46:55.000000', NULL, 1),
(6127294, 902153, 114225, '<td valign="top">Creative title! It''s unfortunate that the background has such bright highlights, they are very distracting.</td>', 'Creative title! It''s unfortunate that the background has such bright highlights, they are very distracting.', '2010-08-11 10:47:57.000000', NULL, 1),
(6127310, 902764, 114225, '<td valign="top">Best photo of the challenge! Perfectly setup, especially he stretch of the next and the ears. Great composition, colors, and details.</td>', 'Best photo of the challenge! Perfectly setup, especially he stretch of the next and the ears. Great composition, colors, and details.', '2010-08-11 11:02:52.000000', NULL, 1),
(6127322, 902764, 118396, '<td valign="top">Great shot - looks like a hero to me!</td>', 'Great shot - looks like a hero to me!', '2010-08-11 11:15:30.000000', NULL, 1),
(6127378, 902895, 96751, '<td valign="top">This would make a great texture!</td>', 'This would make a great texture!', '2010-08-11 12:23:14.000000', NULL, 1),
(6127391, 902592, 119419, '<td valign="top">This is very similar to Ben Robert (Konador) "Love" in "Shadows II"</td>', 'This is very similar to Ben Robert (Konador) "Love" in "Shadows II"', '2010-08-11 12:36:42.000000', NULL, 1),
(6127509, 902964, 100831, '<td valign="top">beautiful. dark and moody and perfect basic good stuff.</td>', 'beautiful. dark and moody and perfect basic good stuff.', '2010-08-11 13:52:51.000000', NULL, 1),
(6127513, 902932, 100831, '<td valign="top">he he he. had to think twice.</td>', 'he he he. had to think twice.', '2010-08-11 13:55:05.000000', NULL, 1),
(6127538, 902387, 117559, '<td valign="top">So far my favourite.</td>', 'So far my favourite.', '2010-08-11 14:21:06.000000', NULL, 1),
(6127541, 902302, 16402, '<td valign="top">cute</td>', 'cute', '2010-08-11 14:22:38.000000', NULL, 1),
(6127543, 902579, 2612, '<td valign="top">My jaw aches just looking at that :-) I don''t like the nose being cropped off, BUT the bonus points for shooting under difficult circumstances more than make up for it.</td>', 'My jaw aches just looking at that :-) I don''t like the nose being cropped off, BUT the bonus points for shooting under difficult circumstances more than make up for it.', '2010-08-11 14:23:13.000000', NULL, 1),
(6127544, 902721, 16402, '<td valign="top">Nice composition</td>', 'Nice composition', '2010-08-11 14:23:26.000000', NULL, 1),
(6127549, 902593, 16402, '<td valign="top">Love the composition! 7</td>', 'Love the composition! 7', '2010-08-11 14:26:03.000000', NULL, 1),
(6127552, 902899, 16402, '<td valign="top">Really like the image, but the title - not so much. 7</td>', 'Really like the image, but the title - not so much. 7', '2010-08-11 14:27:40.000000', NULL, 1),
(6127555, 902725, 8759, '<td valign="top"><u></u></td>', '', '2010-08-11 14:29:48.000000', NULL, 1),
(6127573, 901984, 117474, '<td valign="top">I wonder if this might be a little too artsy for DPC :)<br/>This is an interesting shot. Very interesting, actually. <br/>I like how the in focus subject isn''t all visible to us, and his back faces us. His head''s even out of shot. It''s not something I''d do, cause I''d be too afraid of people''s reactions here. <br/>This is definitely a shot that I''d normally be guilty of voting too quickly on. The title suggests I should look under the wing. And I was initially confused that there wasn''t much of interest under that wing (though there looks to be a monkey head highlight on the bottom that I like). <br/>Now I gather it might be more of a metaphorical title. The feather formation is very interesting on the wing and back and his seem different to the others around him. Not out of the question that he might be their senior/head/alpha male or something. Metaphor being he looks after them. <br/>I might be waaaaay off with my analysis here. But I like it. <br/>After looking at it, and because it got me thinking a lot about the subject, and his relation to those around him (and even what his head looks like), and due to a strong title I think a 7 is appropriate.</td>', 'I wonder if this might be a little too artsy for DPC :)This is an interesting shot. Very interesting, actually. I like how the in focus subject isn''t all visible to us, and his back faces us. His head''s even out of shot. It''s not something I''d do, cause I''d be too afraid of people''s reactions here. This is definitely a shot that I''d normally be guilty of voting too quickly on. The title suggests I should look under the wing. And I was initially confused that there wasn''t much of interest under that wing (though there looks to be a monkey head highlight on the bottom that I like). Now I gather it might be more of a metaphorical title. The feather formation is very interesting on the wing and back and his seem different to the others around him. Not out of the question that he might be their senior/head/alpha male or something. Metaphor being he looks after them. I might be waaaaay off with my analysis here. But I like it. After looking at it, and because it got me thinking a lot about the subject, and his relation to those around him (and even what his head looks like), and due to a strong title I think a 7 is appropriate.', '2010-08-11 15:01:39.000000', NULL, 1),
(6127587, 901986, 100393, '<td valign="top">This composition without any cropping is flat out amazing - especially given the speed of your subjects.</td>', 'This composition without any cropping is flat out amazing - especially given the speed of your subjects.', '2010-08-11 15:14:08.000000', NULL, 1),
(6127618, 902764, 100393, '<td valign="top">I viewed this on my iPad and it display all wrong, 90 degrees about and stretched. I''m glad I left it and revisited it on my full size Mac. This is a great image. May ribbon.</td>', 'I viewed this on my iPad and it display all wrong, 90 degrees about and stretched. I''m glad I left it and revisited it on my full size Mac. This is a great image. May ribbon.', '2010-08-11 15:37:51.000000', NULL, 1),
(6127700, 902590, 96751, '<td valign="top">Power lines, very dynamic image.  Well done in minimal.</td>', 'Power lines, very dynamic image.  Well done in minimal.', '2010-08-11 17:55:55.000000', NULL, 1),
(6127701, 902751, 96751, '<td valign="top">Love the tones here.  Wondering how you pulled it off.</td>', 'Love the tones here.  Wondering how you pulled it off.', '2010-08-11 17:56:13.000000', NULL, 1),
