(6127903, 902049, 38162, '<td valign="top">makes me homesick for pasadena - nice angle here.  gl</td>', 'makes me homesick for pasadena - nice angle here.  gl', '2010-08-12 00:03:50.000000', NULL, 1),
(6127943, 902964, 96751, '<td valign="top">Very cool abstract.  Perfectly exposed.</td>', 'Very cool abstract.  Perfectly exposed.', '2010-08-12 02:27:59.000000', NULL, 1),
(6127944, 902291, 96751, '<td valign="top">Excellent detail and clarity. Nailed the dof.</td>', 'Excellent detail and clarity. Nailed the dof.', '2010-08-12 02:28:40.000000', NULL, 1),
(6127946, 902499, 96751, '<td valign="top">Fabulous!  Was this taken with a Lensbaby?</td>', 'Fabulous!  Was this taken with a Lensbaby?', '2010-08-12 02:29:46.000000', NULL, 1),
(6127947, 902969, 96751, '<td valign="top">Love these star trail images.</td>', 'Love these star trail images.', '2010-08-12 02:29:51.000000', NULL, 1),
(6127948, 902387, 96751, '<td valign="top">He''s all "been there, done that".  Great expression.</td>', 'He''s all "been there, done that".  Great expression.', '2010-08-12 02:30:17.000000', NULL, 1),
(6127949, 902569, 96751, '<td valign="top">Must have used the "vivid" setting!  Very cool.</td>', 'Must have used the "vivid" setting!  Very cool.', '2010-08-12 02:31:02.000000', NULL, 1),
(6127951, 902754, 96751, '<td valign="top">Killer expression.  The head-on position really creates almost a caricature of the bird.  Even though that spot is rather gnarly...</td>', 'Killer expression.  The head-on position really creates almost a caricature of the bird.  Even though that spot is rather gnarly...', '2010-08-12 02:32:07.000000', NULL, 1),
