(6129501, 902719, 30982, '<td valign="top">Great catch of the water spray!  Hard to get action framed well out of the camera - you did a good job of that here.</td>', 'Great catch of the water spray!  Hard to get action framed well out of the camera - you did a good job of that here.', '2010-08-13 22:17:24.000000', NULL, 1),
(6129502, 902714, 30982, '<td valign="top">I like the furry figures in the distance.  Well composed - nice natural framing/composition used knowing you can''t crop.  A bit posed-looking with the foreground figure, but the shot hangs well together anyway.</td>', 'I like the furry figures in the distance.  Well composed - nice natural framing/composition used knowing you can''t crop.  A bit posed-looking with the foreground figure, but the shot hangs well together anyway.', '2010-08-13 22:18:24.000000', NULL, 1),
(6129508, 902727, 30982, '<td valign="top">Oh, I FEEL the rain in this.  Marvelous composition (though I''m sure many don''t agree with me) to get the real girl on the left, the painted girl on the right.  I like this a lot.</td>', 'Oh, I FEEL the rain in this.  Marvelous composition (though I''m sure many don''t agree with me) to get the real girl on the left, the painted girl on the right.  I like this a lot.', '2010-08-13 22:20:43.000000', NULL, 1),
(6129511, 902575, 30982, '<td valign="top">VERY impressive for minimal.  You either have a very clean sensor (no dead pixels) or the camera accomodates those nicely.  Excellent exposure!</td>', 'VERY impressive for minimal.  You either have a very clean sensor (no dead pixels) or the camera accomodates those nicely.  Excellent exposure!', '2010-08-13 22:21:25.000000', NULL, 1),
(6129514, 902597, 30982, '<td valign="top">One of my favorites in this challenge.  A strong composition, very good exposure, and I like the addition of the moving train.  Plus it''s from Germany.  I miss Germany.</td>', 'One of my favorites in this challenge.  A strong composition, very good exposure, and I like the addition of the moving train.  Plus it''s from Germany.  I miss Germany.', '2010-08-13 22:22:21.000000', NULL, 1),
(6129515, 902693, 30982, '<td valign="top">Light is handled beautifully here!</td>', 'Light is handled beautifully here!', '2010-08-13 22:22:38.000000', NULL, 1),
(6129517, 902754, 30982, '<td valign="top">Heh! This one cracks me up!  The look is pricless to begin with and your title really sells the tale.  Nice!</td>', 'Heh! This one cracks me up!  The look is pricless to begin with and your title really sells the tale.  Nice!', '2010-08-13 22:24:42.000000', NULL, 1),
(6129518, 902632, 30982, '<td valign="top">I like doing shots like this.  Sadly, no where here to do them, at least not as good as the mall I frequented in Frankfurt... This one is quite nicely done.  Good in camera crop and good handling of the exposure.  Fun to visit with!</td>', 'I like doing shots like this.  Sadly, no where here to do them, at least not as good as the mall I frequented in Frankfurt... This one is quite nicely done.  Good in camera crop and good handling of the exposure.  Fun to visit with!', '2010-08-13 22:25:46.000000', NULL, 1),
(6129519, 902899, 117831, '<td valign="top">My Pick for Blue! (10) <a href="//www.dpchallenge.com/image.php?IMAGE_ID=900812" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg"/></a></td>', 'My Pick for Blue! (10) ', '2010-08-13 22:26:07.000000', NULL, 1),
(6129520, 902721, 30982, '<td valign="top">Ah, very sweet flare!  Quite an interesting composition as well.  Very nice job with the in-camera framing/compositon.</td>', 'Ah, very sweet flare!  Quite an interesting composition as well.  Very nice job with the in-camera framing/compositon.', '2010-08-13 22:26:18.000000', NULL, 1),
(6129521, 902580, 117831, '<td valign="top">Top 3! <a href="//www.dpchallenge.com/image.php?IMAGE_ID=900812" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg"/></a></td>', 'Top 3! ', '2010-08-13 22:26:18.000000', NULL, 1),
(6129522, 902764, 117831, '<td valign="top">Top 3! <a href="//www.dpchallenge.com/image.php?IMAGE_ID=900812" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/115000-119999/117831/120/Copyrighted_Image_Reuse_Prohibited_900812.jpg"/></a></td>', 'Top 3! ', '2010-08-13 22:26:31.000000', NULL, 1),
(6129523, 902668, 117831, '<td valign="top">great job! very clear! (8)</td>', 'great job! very clear! (8)', '2010-08-13 22:26:45.000000', NULL, 1),
(6129538, 902714, 103032, '<td valign="top">Picture is great, title is good.  This is a great pic; pretty good sharpness throughout the pic, tones are great, lighting gives the pic mood as well as the slow shutter speed (motion blur of the people further down).  Only critique is a bit too much dead space on the right, but for the rule set of this challenge, an awesome image.</td>', 'Picture is great, title is good.  This is a great pic; pretty good sharpness throughout the pic, tones are great, lighting gives the pic mood as well as the slow shutter speed (motion blur of the people further down).  Only critique is a bit too much dead space on the right, but for the rule set of this challenge, an awesome image.', '2010-08-13 23:19:09.000000', NULL, 1),
(6129805, 901644, 61396, '<td valign="top">I like stories with pictures. The blur (lensbaby?) does it.</td>', 'I like stories with pictures. The blur (lensbaby?) does it.', '2010-08-14 10:57:53.000000', NULL, 1),
(6129831, 902592, 101702, '<td valign="top">Nice picture but a complete shoehorn of a title! I would never have got any link to "under" from the pic alone.</td>', 'Nice picture but a complete shoehorn of a title! I would never have got any link to "under" from the pic alone.', '2010-08-14 11:42:41.000000', NULL, 1),
(6129835, 902627, 101702, '<td valign="top">Nice natural shot, but I would have cropped it a bit tighter to lose the legs top right.</td>', 'Nice natural shot, but I would have cropped it a bit tighter to lose the legs top right.', '2010-08-14 11:48:44.000000', NULL, 1);
