(6133475, 901644, 83313, '<td valign="top">I figured you to be one of a handful this might be from. Nice moody stuff. It got a 7 from me.</td>', 'I figured you to be one of a handful this might be from. Nice moody stuff. It got a 7 from me.', '2010-08-18 01:43:40.000000', NULL, 0),
(6133477, 902486, 83313, '<td valign="top">Now that I know the details behind it, I have say this is pretty darn good for handheld at a 1/15th!</td>', 'Now that I know the details behind it, I have say this is pretty darn good for handheld at a 1/15th!', '2010-08-18 01:47:20.000000', NULL, 0),
