(6133483, 902486, 120106, '<td valign="top">Thanks for noticing.  Yes I have practiced quite a bit at taking shots with slow shutter speeds hand held I have gotten pretty good at it. Now if only I could get good at everything else photography has to offer:)<br/> <br/></td>', 'Thanks for noticing.  Yes I have practiced quite a bit at taking shots with slow shutter speeds hand held I have gotten pretty good at it. Now if only I could get good at everything else photography has to offer:) ', '2010-08-18 01:50:48.000000', NULL, 0),
(6133488, 902964, 68504, '<td valign="top">interstitial ambiguities.  getting to know you.</td>', 'interstitial ambiguities.  getting to know you.', '2010-08-18 01:56:47.000000', NULL, 0),
(6133489, 902113, 60862, '<td valign="top">I really enjoyed this, but couldn''t wrap my mind around what it was.  Now I see that the arches actually hang off the roof, not connecting to the ground.</td>', 'I really enjoyed this, but couldn''t wrap my mind around what it was.  Now I see that the arches actually hang off the roof, not connecting to the ground.', '2010-08-18 01:58:50.000000', NULL, 0),
