(6133496, 902964, 60862, '<td valign="top">I liked the shapes and shadows in this, Don.</td>', 'I liked the shapes and shadows in this, Don.', '2010-08-18 02:02:08.000000', NULL, 0),
(6133497, 902932, 60862, '<td valign="top">I liked the photo, but especially appreciated the clever title. :)</td>', 'I liked the photo, but especially appreciated the clever title. :)', '2010-08-18 02:03:23.000000', NULL, 0),
(6133498, 902719, 60862, '<td valign="top">Ah, another VT shot!  I was up in Lake Groton, east of Barre.  Burlington''s about 90 minutes away.  I loved the guy''s hat!  And I was impressed with the frozen action of the water and the composition with a fast-moving subject in a no-crop challenge.</td>', 'Ah, another VT shot!  I was up in Lake Groton, east of Barre.  Burlington''s about 90 minutes away.  I loved the guy''s hat!  And I was impressed with the frozen action of the water and the composition with a fast-moving subject in a no-crop challenge.', '2010-08-18 02:05:30.000000', NULL, 0),
(6133501, 902620, 60862, '<td valign="top">Great color, great composition.  Congrats on top 10!</td>', 'Great color, great composition.  Congrats on top 10!', '2010-08-18 02:06:00.000000', NULL, 0),
(6133504, 902764, 100727, '<td valign="top">This is a great shot.  He should be in movies! :)</td>', 'This is a great shot.  He should be in movies! :)', '2010-08-18 02:08:15.000000', NULL, 0),
